style.css:
@-moz-document domain("roblox.com") {
:root{
    --osaka-main:#D97582;
    --osaka-dark:#A94752;
    --osaka-deep:#7A2C34;
    --osaka-light:#E98A95;
    --osaka-white:#F7F0F0;
}

/* FUNDO */

body {
    background:
    linear-gradient(
        rgba(122,44,52,.65),
        rgba(122,44,52,.65)
    ),
    url(https://cdn.wallpapersafari.com/44/29/ZBb3VE.jpg) !important;

    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
}

/* REMOVE FUNDOS PADRÃO */

.container-main,
.content,
.content-body,
.rbx-body,
#container-main {
    background: transparent !important;
}

/* NAVBAR */

.navbar,
.navbar-fixed-top,
.header {
    background: rgba(122,44,52,.90) !important;
    backdrop-filter: blur(12px);
    border-bottom: 1px solid rgba(255,255,255,.15);
}

/* SIDEBAR */

.left-col,
.nav-menu,
.menu-vertical,
.menu-container {

    background: rgba(169,71,82,.65) !important;

    backdrop-filter: blur(15px);

    border-radius: 16px;
}

/* CARDS */

.game-card-container,
.game-card,
.friend-tile,
.list-item,
.section-content {

    background: rgba(233,138,149,.18) !important;

    backdrop-filter: blur(18px);

    border: 1px solid rgba(255,255,255,.18);

    border-radius: 18px;

    transition: .25s;
}

/* HOVER */

.game-card:hover,
.friend-tile:hover {

    transform: translateY(-4px);

    box-shadow:
    0 0 15px rgba(233,138,149,.4);

    border-color: var(--osaka-light);
}

/* TEXTO */

h1,
h2,
h3,
h4,
h5,
span,
p,
a {

    color: var(--osaka-white) !important;
}

/* BOTÕES */

.btn-primary,
.btn-secondary {

    background:
    linear-gradient(
        135deg,
        var(--osaka-light),
        var(--osaka-main)
    ) !important;

    border: none !important;

    color: white !important;

    border-radius: 12px;
}

/* BOTÃO HOVER */

.btn-primary:hover,
.btn-secondary:hover {

    background:
    linear-gradient(
        135deg,
        #f2a3ac,
        #d97582
    ) !important;
}

/* BARRA DE PESQUISA */

input,
.search-input {

    background:
    rgba(255,255,255,.10) !important;

    border:
    1px solid rgba(255,255,255,.15) !important;

    color: white !important;

    border-radius: 12px !important;
}

/* SCROLLBAR */

::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: var(--osaka-deep);
}

::-webkit-scrollbar-thumb {
    background: var(--osaka-light);
    border-radius: 50px;
}

/* AVATAR */

.avatar,
.avatar-card {

    border:
    3px solid var(--osaka-light);

    box-shadow:
    0 0 20px rgba(233,138,149,.6);
}

/* EFEITO GLASS */

.section,
.card,
.profile-header,
.friends-list {

    background:
    rgba(255,255,255,.08) !important;

    backdrop-filter:
    blur(18px);

    border:
    1px solid rgba(255,255,255,.12);

    border-radius: 20px;
}

/* LOGO ROSA */

.navbar .icon-logo-r,
.navbar .icon-logo {

    filter:
    brightness(1.2)
    saturate(1.3)
    hue-rotate(-15deg);
}
}
